import React, { useEffect, useRef } from 'react';
import '../styles/ParticleRings.css';

/**
 * Two concentric particle tori that move with Jarvis's voice.
 *
 * RENDERING
 * ---------
 * Canvas 2D writing directly into an ImageData buffer, at a deliberately low
 * internal resolution that CSS then scales up with `image-rendering:
 * pixelated`. Two reasons:
 *
 *   1. It is genuinely pixelated rather than a smooth render shrunk down —
 *      each particle lands on a real pixel of the buffer.
 *   2. It is fast. ~7000 fillRect calls per frame is borderline at 60fps;
 *      writing bytes into a typed array is not.
 *
 * No 3D library. The projection is a dozen lines of trigonometry, and adding
 * three.js for two tori would be ~600KB for maths that fits on one screen.
 *
 * AUDIO
 * -----
 * `level` is the RMS of the PCM actually reaching the speaker (see
 * voice/audio_level.py), 0..1. It drives radial displacement, brightness and
 * spin, so the shape breathes with the voice instead of animating blindly.
 */

// Internal buffer size. Small on purpose — this IS the pixel grid.
const W = 460;
const H = 460;

const RING_COUNT = 2;
const PARTICLES_PER_RING = 2600;

const FOCAL = 620;          // perspective strength
const BASE_RADIUS = 118;    // main ring radius
const TUBE_RADIUS = 34;     // thickness of each ring

export default function ParticleRings({ state = 'offline', level = 0 }) {
  const canvasRef = useRef(null);
  const frameRef = useRef(0);
  // Read inside the animation loop without restarting it on every update.
  const levelRef = useRef(0);
  const stateRef = useRef(state);
  const smoothRef = useRef(0);

  useEffect(() => { levelRef.current = level; }, [level]);
  useEffect(() => { stateRef.current = state; }, [state]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false });
    const image = ctx.createImageData(W, H);
    const buf = image.data;

    // Particle geometry is fixed at construction; only the rotation and the
    // audio displacement change per frame. Precomputing the trig here keeps
    // the hot loop to multiplies and adds.
    const particles = [];
    for (let r = 0; r < RING_COUNT; r++) {
      for (let i = 0; i < PARTICLES_PER_RING; i++) {
        const u = Math.random() * Math.PI * 2;   // around the ring
        const v = Math.random() * Math.PI * 2;   // around the tube
        // Bias toward the tube surface so the rings read as shells rather
        // than solid sausages — that is what gives the reference its airy,
        // cloud-like edge.
        const shell = 0.55 + Math.pow(Math.random(), 0.4) * 0.45;
        particles.push({
          ring: r,
          cu: Math.cos(u), su: Math.sin(u),
          cv: Math.cos(v), sv: Math.sin(v),
          shell,
          // Per-particle phase so they shimmer independently rather than
          // pulsing as one rigid body.
          phase: Math.random() * Math.PI * 2,
          twinkle: 0.6 + Math.random() * 0.4,
        });
      }
    }

    const COLOURS = {
      offline:   [70, 90, 110],
      idle:      [120, 210, 255],
      listening: [150, 240, 255],
      thinking:  [130, 200, 255],
      speaking:  [255, 200, 130],
      error:     [255, 110, 120],
    };

    let raf;
    let t = 0;

    const draw = () => {
      const st = stateRef.current;
      const target = st === 'offline' ? 0 : levelRef.current;

      // Ease toward the reported level. The publisher already smooths, but
      // it updates ~10x/second while this runs at 60 — interpolating here
      // is what removes the stepping.
      smoothRef.current += (target - smoothRef.current) * 0.18;
      const amp = smoothRef.current;

      const idle = st === 'idle' || st === 'offline';
      const speed = st === 'offline' ? 0.10 : idle ? 0.28 : 0.28 + amp * 1.5;
      t += 0.006 * speed;

      // Fade rather than clear, leaving a short motion trail.
      for (let i = 0; i < buf.length; i += 4) {
        buf[i] *= 0.62;
        buf[i + 1] *= 0.62;
        buf[i + 2] *= 0.62;
        buf[i + 3] = 255;
      }

      const [cr, cg, cb] = COLOURS[st] || COLOURS.idle;

      const ax = Math.sin(t * 0.7) * 0.45 + 0.55;  // tumble
      const ay = t;
      const cosX = Math.cos(ax), sinX = Math.sin(ax);
      const cosY = Math.cos(ay), sinY = Math.sin(ay);

      const cx = W / 2;
      const cy = H / 2;
      const breathe = 1 + amp * 0.34;

      for (let p = 0; p < particles.length; p++) {
        const q = particles[p];

        // Torus point. The second ring is tilted a quarter turn so the two
        // interlock the way they do in the reference.
        const tube = TUBE_RADIUS * q.shell * breathe;
        const ringR = BASE_RADIUS + (q.ring === 1 ? 26 : -26);

        let x = (ringR + tube * q.cv) * q.cu;
        let y = (ringR + tube * q.cv) * q.su;
        let z = tube * q.sv;

        if (q.ring === 1) {
          // Rotate this ring about X so the pair sits concentric but crossed.
          const ty = y * 0.20 - z * 0.98;
          const tz = y * 0.98 + z * 0.20;
          y = ty; z = tz;
        }

        // Voice pushes particles outward along their own radius.
        if (amp > 0.001) {
          const push = 1 + amp * 0.22 * Math.sin(q.phase + t * 9);
          x *= push; y *= push;
        }

        // Rotate: Y then X.
        const x1 = x * cosY + z * sinY;
        const z1 = -x * sinY + z * cosY;
        const y2 = y * cosX - z1 * sinX;
        const z2 = y * sinX + z1 * cosX;

        const denom = FOCAL + z2;
        if (denom <= 1) continue;
        const scale = FOCAL / denom;

        const sx = (cx + x1 * scale) | 0;
        const sy = (cy + y2 * scale) | 0;
        if (sx < 0 || sx >= W || sy < 0 || sy >= H) continue;

        // Depth and per-particle shimmer decide brightness. Nearer particles
        // are brighter, which is what reads as three-dimensional in a flat
        // field of identical dots.
        const depth = Math.max(0, Math.min(1, (scale - 0.68) / 0.62));
        const shimmer = 0.65 + 0.35 * Math.sin(q.phase + t * 6) * q.twinkle;
        const b = depth * shimmer * (0.55 + amp * 0.65);

        const idx = (sy * W + sx) * 4;
        const nr = buf[idx] + cr * b;
        const ng = buf[idx + 1] + cg * b;
        const nb = buf[idx + 2] + cb * b;
        buf[idx] = nr > 255 ? 255 : nr;
        buf[idx + 1] = ng > 255 ? 255 : ng;
        buf[idx + 2] = nb > 255 ? 255 : nb;
      }

      ctx.putImageData(image, 0, 0);
      raf = requestAnimationFrame(draw);
      frameRef.current = raf;
    };

    draw();
    return () => cancelAnimationFrame(raf);
  }, []);   // built once; state and level are read through refs

  return (
    <div className={`prings prings-${state}`}>
      <div className="prings-glow" />
      <canvas ref={canvasRef} width={W} height={H} className="prings-canvas" />
    </div>
  );
}
